/**
 * 今日重点（Daily Focus）— P0 改进 #1
 *
 * 问题：玩家面对 35+ 街头工作、6 行业投资、20+ 标签界面，
 *   每日开局有"决策瘫痪"。Hermes 评估指出"信息层级过载（D）"。
 *
 * 设计参考：
 * - 《大多数》"今日目标"区块（侧边栏黄色挂条）
 * - BitLife "Top Recommendations"
 * - This War of Mine 早晨清单
 *
 * 实现：基于 state 推断 1-3 条"今日最该做"，渲染到 #daily-focus-section
 *   每条 ≤ 14 字，单 emoji 起头；点击关闭则当日不再显示。
 *
 * 规则采用"加权评分 → 取前 3"算法：
 *   1) 紧急健康/疲劳/食物 (权重 100)
 *   2) 紧急债务到期      (权重 90)
 *   3) 装备临近报废      (权重 70)
 *   4) 当前可领的成就    (权重 50)
 *   5) 行业热度异常机会  (权重 40)
 *   6) 节日抢钱窗口      (权重 30)
 *   7) 梦想里程碑接近    (权重 20)
 */

(function () {
  function _fmt(text) {
    return text;
  }

  function _collectCandidates(state) {
    var out = [];
    var p = state.player || {};
    var n = state.needs || {};
    var r = state.resources || {};
    var s = state.status || {};

    // 健康危机
    if ((s.health || 100) < 35) {
      out.push({
        w: 100,
        icon: "🚑",
        text: "去医院或药店看病",
        hint: "健康<35，再低会昏迷",
      });
    }
    if ((n.hunger || 100) < 30) {
      out.push({
        w: 95,
        icon: "🍜",
        text: "买饭吃，别饿着",
        hint: "饥饿过低损耗体力",
      });
    }
    if ((n.fatigue || 0) > 80) {
      out.push({
        w: 92,
        icon: "🛏️",
        text: "回家睡一觉",
        hint: "疲劳过高效率折半",
      });
    }
    if ((n.happiness || 50) < 20) {
      out.push({
        w: 88,
        icon: "🎮",
        text: "找件开心的事做",
        hint: "心情过低会触发心理事件",
      });
    }

    // 债务紧迫
    var vd = r.villageDebt || 0;
    if (vd > 0) {
      var vi = r.villageDebtInterest || 0;
      if (vi > 0 && vd > 3000 && p.day && p.day > 30) {
        out.push({
          w: 90,
          icon: "🏘️",
          text: "尽快还村长一些钱",
          hint: "利息复利越滚越大",
        });
      } else if (vd > 0 && p.day && p.day > 80) {
        out.push({
          w: 60,
          icon: "🏘️",
          text: "找时间还村长债",
          hint: "拖太久会被催债事件",
        });
      }
    }

    // 装备耐久
    var equipped = (state.equipment && state.equipment.equipped) || {};
    var dur = state._equipmentDurability || {};
    Object.keys(equipped).forEach(function (slot) {
      var itemId = equipped[slot];
      if (!itemId) return;
      var d = dur[itemId];
      if (!d || typeof d.current !== "number" || typeof d.max !== "number")
        return;

