2696	function renderMapTab(state, parent) {
2697	  const locKey = state.trade.currentLocation;
2698	  const loc = getLocation(locKey);
2699	  const reachable = new Set(getReachableLocations(locKey));
2700	  reachable.add(locKey);
2701	
2702	  const container = document.createElement("div");
2703	  container.style.cssText = "display:flex;flex-direction:column;gap:16px;";
2704	
2705	  // 标题
2706	  const title = document.createElement("div");
2707	  title.innerHTML = `
2708	    <h3 style="color:var(--text-muted);margin-bottom:4px;">🗺️ 城市地图</h3>
2709	    <p style="font-size:12px;color:var(--text-secondary);">
