2711	    </p>
2712	  `;
2713	  container.appendChild(title);
2714	
2715	  // === ⭐ 快速出行置顶区（解决"地图没了"问题） ===
2716	  const reachableList = Array.from(reachable).filter((k) => k !== locKey);
2717	  if (reachableList.length > 0) {
2718	    const quick = document.createElement("div");
2719	    quick.style.cssText =
2720	      "padding:14px;background:linear-gradient(135deg, var(--bg-card), rgba(0,180,216,0.08));border:1px solid var(--accent);border-radius:var(--radius-md);";
2721	    quick.innerHTML = `
2722	      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;">
2723	        <h4 style="color:var(--accent);margin:0;font-size:14px;">🚶 快速出行</h4>
2724	        <span style="font-size:10px;color:var(--text-muted);">从 ${loc ? loc.name : "当前位置"} 出发</span>
2725	      </div>
2726	      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:8px;">
2727	    `;
2728	    for (const destKey of reachableList) {
2729	      const dest = getLocation(destKey);
2730	      if (!dest) continue;
2731	      const destType =
2732	        dest.type === "commercial"
2733	          ? "🛒商业"
2734	          : dest.type === "industrial"
2735	            ? "🏭工业"
2736	            : dest.type === "residential"
2737	              ? "🏘️居住"
2738	              : dest.type === "service"
2739	                ? "🏥服务"
2740	                : dest.type === "education"
2741	                  ? "📚教育"
2742	                  : dest.type === "corporate"
2743	                    ? "🏢职场"
2744	                    : dest.type === "recreation"
2745	                      ? "🌳休闲"
2746	                      : dest.type === "institutional"
2747	                        ? "🏫机构"
2748	                        : "📍其他";
2749	      quick.innerHTML += `
2750	        <button class="quick-travel-btn" data-dest="${destKey}" style="
2751	          padding:10px 12px;
2752	          background:var(--bg-secondary);
2753	          border:1px solid var(--border);
2754	          border-radius:6px;
2755	          cursor:pointer;
2756	          text-align:left;
2757	          color:var(--text-primary);
2758	          font-size:12px;
2759	          transition:all 0.15s;
2760	        " onmouseover="this.style.borderColor='var(--accent)';this.style.background='rgba(0,180,216,0.06)';"
2761	           onmouseout="this.style.borderColor='var(--border)';this.style.background='var(--bg-secondary)';">
2762	          <div style="font-weight:600;color:var(--accent);">📍 ${dest.name}</div>
2763	          <div style="font-size:10px;color:var(--text-muted);margin-top:2px;">${destType}</div>
2764	          <div style="font-size:10px;color:var(--text-secondary);margin-top:2px;line-height:1.3;">${dest.desc}</div>
2765	        </button>
2766	      `;
2767	    }
2768	    quick.innerHTML += "</div>";
2769	    container.appendChild(quick);
2770	  }
2771	
2772	  // === v3.0 交通方式选择（共享单车/地铁/打车）===
2773	  // 设计参考：北上广真实数据
2774	  //   共享单车 ¥2/15分钟，仅适合相邻地点（≤1跳），最快到非商业区
2775	  //   地铁 ¥4 固定，仅可到地铁沿线大站（科技园/商业区/医院/学校/培训中心/娱乐区）
2776	  //   打车 ¥15-50 按距离，可达任何已探索地点，最快但最贵
2777	  const transitWrap = document.createElement("div");
