2784	    </p>
2785	    <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;">
2786	      <button class="transit-btn" data-mode="bike" style="
2787	        padding:10px 6px;background:var(--bg-secondary);border:1px solid var(--border);
2788	        border-radius:6px;cursor:pointer;text-align:left;color:var(--text-primary);font-size:12px;">
2789	        <div style="font-weight:600;color:var(--success);">🚲 共享单车</div>
2790	        <div style="font-size:10px;color:var(--text-muted);margin-top:2px;">¥3 · 2跳内可达</div>
2791	        <div style="font-size:10px;color:var(--text-secondary);margin-top:2px;">比步行快、比打车便宜</div>
2792	      </button>
2793	      <button class="transit-btn" data-mode="metro" style="
2794	        padding:10px 6px;background:var(--bg-secondary);border:1px solid var(--border);
2795	        border-radius:6px;cursor:pointer;text-align:left;color:var(--text-primary);font-size:12px;">
2796	        <div style="font-weight:600;color:var(--accent);">🚇 地铁</div>
2797	        <div style="font-size:10px;color:var(--text-muted);margin-top:2px;">¥4 · 地铁8站覆盖</div>
2798	        <div style="font-size:10px;color:var(--text-secondary);margin-top:2px;">科技园/商业区/医院/城中村等</div>
2799	      </button>
2800	      <button class="transit-btn" data-mode="taxi" style="
2801	        padding:10px 6px;background:var(--bg-secondary);border:1px solid var(--border);
2802	        border-radius:6px;cursor:pointer;text-align:left;color:var(--text-primary);font-size:12px;">
2803	        <div style="font-weight:600;color:var(--warning);">🚕 打车</div>
2804	        <div style="font-size:10px;color:var(--text-muted);margin-top:2px;">¥10-40 按距离</div>
2805	        <div style="font-size:10px;color:var(--text-secondary);margin-top:2px;">最快的点对点交通</div>
2806	      </button>
2807	    </div>
2808	    <div id="transit-result" style="margin-top:10px;font-size:12px;color:var(--text-secondary);"></div>
2809	  `;
2810	  container.appendChild(transitWrap);
2811	
