function renderActionsTab(state, parent) {
  var actions = getAvailableActions(state);

  // === 地点氛围描写（每日轮换，让城市有生命感）===
  if (typeof getLocationFlavor === "function") {
    var locId = state.trade && state.trade.currentLocation;
    var flavorText = getLocationFlavor(locId, state.player.day);
    if (flavorText) {
      var flavorBox = document.createElement("div");
      flavorBox.style.cssText =
        "margin-bottom:12px;padding:9px 12px;background:rgba(255,255,255,0.03);border-left:3px solid var(--border);border-radius:0 6px 6px 0;color:var(--text-muted);font-size:12px;font-style:italic;line-height:1.5;";
      flavorBox.textContent = flavorText;
      parent.appendChild(flavorBox);
    }
  }

  // === 今日智能建议（心智驱动，不限数量，滚动展示）===
  {
    var tips = getDailyActionTips(state);
    if (tips.length > 0) {
      var tipBox = document.createElement("div");
      tipBox.style.cssText =
        "margin-bottom:14px;padding:10px 12px;background:rgba(74,158,92,0.06);border:1px solid rgba(74,158,92,0.25);border-radius:8px;";
      var mental = (state.player && state.player.mental) || 0;
      var mentalTag =
        mental >= 80
          ? "🧠 专家洞察"
          : mental >= 60
            ? "💡 进阶建议"
            : "💡 今日建议";
      // 标题行（静态文字，safe to innerHTML）
      var titleDiv = document.createElement("div");
      titleDiv.style.cssText =
        "font-size:10px;color:var(--accent);font-weight:700;margin-bottom:6px;letter-spacing:0.5px;";
      titleDiv.innerHTML =
        mentalTag +
        ' <span style="font-size:9px;color:var(--text-muted);font-weight:400;">（心智' +
        mental +
        "）</span>";
      tipBox.appendChild(titleDiv);
      // 建议列表（用 textContent 避免 XSS）
      var listDiv = document.createElement("div");
      listDiv.style.cssText =
        "max-height:110px;overflow-y:auto;padding-right:2px;";
      tips.forEach(function (t) {
        var item = document.createElement("div");
        item.style.cssText =
          "font-size:12px;color:var(--text-secondary);padding:2px 0;border-bottom:1px solid rgba(255,255,255,0.04);";
        item.textContent = t;
        listDiv.appendChild(item);
      });
      tipBox.appendChild(listDiv);
      parent.appendChild(tipBox);
    }
  }

  // === 频次追踪 + 智能排序 ===
  if (typeof ActionSort !== "undefined" && ActionSort.sortActions) {
    // 包装所有行动的 handler，记录点击频次
    var freq =
      state.stats && state.stats.actionFreq ? state.stats.actionFreq : {};
    var firstUse =
      state.stats && state.stats.actionFirstUse
        ? state.stats.actionFirstUse
        : {};

    for (var _ai = 0; _ai < actions.length; _ai++) {
      (function (_act) {
        if (_act.id && !_act.disabled && typeof _act.handler === "function") {
          var _orig = _act.handler;
          var _aid = _act.id;
          _act.handler = function () {
            if (typeof freq[_aid] === "undefined") {
              freq[_aid] = 0;
              if (state && state.player) firstUse[_aid] = state.player.day;
            }
            freq[_aid]++;
            return _orig.apply(this, arguments);
          };
        }
      })(actions[_ai]);
    }

    // 多层排序（含新行动助力）
    actions = ActionSort.sortActions(actions, state);
  }

  // === ✨ 新行动助力条（首次使用后 3 天内置顶展示） ===
  if (typeof ActionSort !== "undefined" && ActionSort.isActionNew) {
    var newActions = actions.filter(function (a) {
      return !a.disabled && ActionSort.isActionNew(a.id, state);
    });
    if (newActions.length > 0) {
      var newBox = document.createElement("div");
      newBox.style.cssText =
        "margin-bottom:14px;padding:10px 14px;background:linear-gradient(135deg, rgba(255,215,0,0.06), rgba(255,165,0,0.04));border:1px solid rgba(255,215,0,0.3);border-radius:var(--radius-md);";
      var newTitle = document.createElement("div");
      newTitle.style.cssText =
        "font-size:11px;color:var(--warning);font-weight:700;margin-bottom:6px;letter-spacing:0.5px;";
      newTitle.innerHTML =
        "✨ 新行动 — 首次解锁 3 天内排序靠前 <span style='font-size:9px;color:var(--text-muted);font-weight:400;'>（今天第 " +
        (state.player ? state.player.day : "?") +
        " 天）</span>";
      newBox.appendChild(newTitle);
      var newGrid = document.createElement("div");
      newGrid.className = "action-cards";
      newGrid.style.gridTemplateColumns =
        "repeat(auto-fill, minmax(160px, 1fr))";
      for (var _n = 0; _n < newActions.length; _n++) {
        newGrid.appendChild(createActionCard(newActions[_n], state));
      }
      newBox.appendChild(newGrid);
      parent.appendChild(newBox);
    }
  }

  // 分离出行和其他行动
  const travelActions = actions.filter((a) => a.id.startsWith("travel_"));
  const housingActions = actions.filter(
    (a) => a.id.startsWith("housing_") || a.id.startsWith("storage_"),

