content.content:
1	/**
2	 * 今日重点（Daily Focus）— P0 改进 #1
3	 *
4	 * 问题：玩家面对 35+ 街头工作、6 行业投资、20+ 标签界面，
5	 *   每日开局有"决策瘫痪"。Hermes 评估指出"信息层级过载（D）"。
6	 *
7	 * 设计参考：
8	 * - 《大多数》"今日目标"区块（侧边栏黄色挂条）
9	 * - BitLife "Top Recommendations"
10	 * - This War of Mine 早晨清单
11	 *
12	 * 实现：基于 state 推断 1-3 条"今日最该做"，渲染到 #daily-focus-section
13	 *   每条 ≤ 14 字，单 emoji 起头；点击关闭则当日不再显示。
14	 *
15	 * 规则采用"加权评分 → 取前 3"算法：
16	 *   1) 紧急健康/疲劳/食物 (权重 100)
17	 *   2) 紧急债务到期      (权重 90)
18	 *   3) 装备临近报废      (权重 70)
19	 *   4) 当前可领的成就    (权重 50)
20	 *   5) 行业热度异常机会  (权重 40)
21	 *   6) 节日抢钱窗口      (权重 30)
22	 *   7) 梦想里程碑接近    (权重 20)
23	 */
24	
25	(function () {
26	  function _fmt(text) {
27	    return text;
28	  }
29	
30	  function _collectCandidates(state) {
31	    var out = [];
32	    var p = state.player || {};
33	    var n = state.needs || {};
34	    var r = state.resources || {};
35	    var s = state.status || {};
36	
37	    // 健康危机
38	    if ((s.health || 100) < 35) {
39	      out.push({
40	        w: 100,
41	        icon: "🚑",
42	        text: "去医院或药店看病",
43	        hint: "健康<35，再低会昏迷",
44	      });
45	    }
46	    if ((n.hunger || 100) < 30) {
47	      out.push({
48	        w: 95,
49	        icon: "🍜",
50	        text: "买饭吃，别饿着",
51	        hint: "饥饿过低损耗体力",
52	      });
53	    }
54	    if ((n.fatigue || 0) > 80) {
55	      out.push({
56	        w: 92,
57	        icon: "🛏️",
58	        text: "回家睡一觉",
59	        hint: "疲劳过高效率折半",
60	      });
61	    }
62	    if ((n.happiness || 50) < 20) {
63	      out.push({
64	        w: 88,
65	        icon: "🎮",
66	        text: "找件开心的事做",
67	        hint: "心情过低会触发心理事件",
68	      });
69	    }
70	
71	    // 债务紧迫
72	    var vd = r.villageDebt || 0;
73	    if (vd > 0) {
74	      var vi = r.villageDebtInterest || 0;
75	      if (vi > 0 && vd > 3000 && p.day && p.day > 30) {
76	        out.push({
77	          w: 90,
78	          icon: "🏘️",
79	          text: "尽快还村长一些钱",
80	          hint: "利息复利越滚越大",
81	        });
82	      } else if (vd > 0 && p.day && p.day > 80) {
83	        out.push({
84	          w: 60,
85	          icon: "🏘️",
86	          text: "找时间还村长债",
87	          hint: "拖太久会被催债事件",
88	        });
89	      }
90	    }
91	
92	    // 装备耐久
93	    var equipped = (state.equipment && state.equipment.equipped) || {};
94	    var dur = state._equipmentDurability || {};
95	    Object.keys(equipped).forEach(function (slot) {
96	      var itemId = equipped[slot];
97	      if (!itemId) return;
98	      var d = dur[itemId];
99	      if (!d || typeof d.current !== "number" || typeof d.max !== "number")
100	        return;
101	      var pct = d.current / d.max;
102	      if (pct < 0.2) {
103	        out.push({
104	          w: 70,
105	          icon: "🔧",
106	          text: "修一下装备别报废",
107	          hint: itemId + " 耐久仅 " + Math.round(pct * 100) + "%",
108	        });
109	      }
110	    });
111	
112	    // 节日抢钱
113	    if (typeof getActiveFestival === "function") {
114	      try {
115	        var fes = getActiveFestival(state);
116	        if (fes && fes.id) {
117	          out.push({
118	            w: 30,
119	            icon: "🎊",
120	            text: "节日窗口：摆摊好时机",
121	            hint: fes.name + " 期间客流暴增",
122	          });
123	        }
124	      } catch (e) {
125	        /* ignore */
126	      }
127	    }
