1	/**
2	 * 每日结算管线 — 声明式步骤编排
3	 *
4	 * 将 endDay 的 14 步硬编码拆为独立管线步骤，每步自声明：
5	 *   name: 唯一标识
6	 *   fn: 执行函数
7	 *   after: 依赖的前置步骤（可选）
8	 *   skipOnExtreme: 极端状态时是否跳过（默认 true）
9	 *
10	 * 架构原则：新增结算逻辑只需向 DAILY_PIPELINE 数组添加一个步骤对象，
11	 * 不需要修改 endDay 的主流程。
12	 *
13	 * MiniMax 友好：每个步骤的输入输出清晰，依赖声明显式化。
14	 */
15	
16	/** 每日结算步骤管线（按顺序执行） */
17	const DAILY_PIPELINE = [
18	  // === 基础递进 ===
19	  {
20	    name: "day_increment",
21	    fn: function (state) {
22	      state.player.day++;
23	      state.player.actionPoints = state.player.maxActionPoints;
24	      state.player.timeSlot = "morning";
25	    },
26	  },
27	
28	  // === v3.3 W2-T3: 剧本专属开局链（在需求衰减之前触发）===
29	  {
30	    name: "scenario_start_chain",
31	    fn: function (state) {
32	      if (typeof checkScenarioStartChain === "function") {
33	        checkScenarioStartChain(state);
34	      }
35	    },
36	  },
37	
38	  // === 需求衰减 ===
39	  {
40	    name: "needs_decay",
41	    fn: function (state) {
42	      applyNeedsDecay(state);
43	    },
44	  },
45	
46	  // === 状态交叉影响 ===
47	  {
48	    name: "status_interactions",
49	    fn: function (state) {
50	      applyStatusInteractions(state);
51	    },
52	  },
53	
54	  // === 资产关联维持性开支（P1-5：后期"钱太多没事做"） ===
55	  {
56	    name: "wealth_overhead",
57	    fn: function (state) {
58	      if (typeof applyWealthBasedOverhead === "function") {
59	        applyWealthBasedOverhead(state);
60	      }
61	    },
62	  },
63	
64	  // === 睡眠恢复 ===
65	  {
66	    name: "sleep_recovery",
67	    fn: function (state) {
68	      var house = getCurrentHousing(state);
69	      var recovery = house.fatigueRecovery;
70	      var penalty = state._fatigueRecoveryPenalty || 1.0;
71	      // 命名疾病的疲劳恢复倍率叠加（失眠症等）
72	      if (typeof getIllnessAttrDebuffs === "function") {
73	        var ad = getIllnessAttrDebuffs(state);
74	        if (ad.fatigueRecoveryMult && ad.fatigueRecoveryMult < 1) {
75	          penalty *= ad.fatigueRecoveryMult;
76	        }
77	      }
78	      if (penalty < 1.0) {
79	        StateManager.addMessage(
80	          "😢 睡眠质量很差，疲劳恢复打了" + Math.round(penalty * 100) + "%折。",
81	          "warning",
82	        );
83	      }
84	      state.needs.fatigue = Math.max(
85	        0,
86	        state.needs.fatigue - Math.round(recovery * penalty),
87	      );
88	      delete state._fatigueRecoveryPenalty;
89	      state.needs.hygiene = Math.min(
90	        100,
91	        state.needs.hygiene + (house.hygieneBonus || 0),
92	      );
93	      state.needs.happiness = Math.max(
94	        0,
95	        Math.min(100, state.needs.happiness - 3 + (house.happinessBonus || 0)),
96	      );
97	      // 王大婶好感30解锁每日带饭（饥饱+15）
98	      if (state.flags.auntWangMeal) {
99	        state.needs.hunger = Math.min(100, state.needs.hunger + 15);
100	        if (Random.chance(0.3)) {
101	          StateManager.addMessage(
102	            "🍱 早上发现门口有王大婶留的饭菜，暖心。",
103	            "info",
104	          );
105	        }
106	      }
107	    },
108	  },
109	
110	  // === 房租 ===
111	  {
112	    name: "rent",
113	    fn: function (state) {
114	      var house = getCurrentHousing(state);
115	      var selfLiving =
116	        state.investment && state.investment.selfLivePropertyId != null;
117	      var locKey = state.housing?.rentedAt || "slum";
