150	        state.housing.storageCapacity > 0
151	      ) {
152	        var storageRent = state.housing.storageCapacity >= 500 ? 50 : 20;
153	        if (state.resources.cash >= storageRent) {
154	          state.resources.cash -= storageRent;
155	          addDailyTransaction(
156	            state,
157	            "expense",
158	            "rent",
159	            storageRent,
160	            "仓库租金",
161	          );
162	        } else {
163	          StateManager.addMessage("⚠️ 付不起仓库租金，仓库被收回。", "danger");
164	          state.housing.storageRented = false;
165	          state.housing.storageCapacity = 0;
166	          var houseInfo =
167	            typeof getCurrentHousing === "function"
168	              ? getCurrentHousing(state)
169	              : null;
170	          var baseCap = houseInfo ? houseInfo.capacity : 20;
171	          state.inventory.capacity = baseCap;
172	        }
173	      }
174	    },
175	  },
176	
177	  // === v3.8: 住房维护费（按住房等级月度扣除） ===
